// Alertmanager sends the alert inside the webhook body.
const body = $json.body || {};
const labels = body.commonLabels || {};
const annotations = body.commonAnnotations || {};

return {
  json: {
    status: body.status || "unknown",
    alertname: labels.alertname || "unknown",
    severity: labels.severity || "none",
    service: labels.service || "unknown",
    summary: annotations.summary || annotations.description || "",
    runbook_url: annotations.runbook_url || "",
    alert_count: (body.alerts || []).length,
  },
};

